tool_input.command:
for offset in 0 7 14 21 28 35; do 
  date_str=$(node -e "import('node:util').then(() => console.log(new Date(Date.UTC(2026, 9, 25 + $offset)).toISOString().slice(0, 10)))");
  echo -n "On $date_str: ";
  node bin/subtrack.js renewals --file /tmp/final-test.json --today "$date_str" --within 1 | grep "meal kit" || echo "No meal kit renewal";
done
